export type DorcIconName = (typeof DORC_ICON_NAMES)[number];
export type DorcIconId = `dorc:${DorcIconName}`;

export function dorcIcon(name: DorcIconName): DorcIconId {
  return `dorc:${name}`;
}

interface DorcIconDef {
  readonly viewBox: string;
  readonly svg: string;
}

const deviconToSvg = (paths: readonly string[]): string =>
  paths.map(d => `<path d="${d}"></path>`).join('');

