if (!document.querySelector('vaadin-iconset[name="dorc"]')) {
  const template = document.createElement('template');
  const defs = DORC_ICON_NAMES.map(name => {
    const { viewBox, svg } = DORC_ICON_DEFS[name];
    return `<g id="${name}" viewBox="${viewBox}">${svg}</g>`;
  }).join('');

  template.innerHTML = `<vaadin-iconset name="dorc" size="24"><svg><defs>${defs}</defs></svg></vaadin-iconset>`;
  document.head.appendChild(template.content);
}
